#!/usr/bin/env python3
"""Writes CRATES.md: the Rust crates linked into the Mermaid import (normal dependencies of ad-merman).

    cd third_party/merman && python3 list_crates.py
"""
import json
import pathlib
import subprocess

here = pathlib.Path(__file__).resolve().parent
meta = json.loads(subprocess.run(["cargo", "metadata", "--format-version", "1", "--locked"], cwd=here, check=True,
                                 capture_output=True, text=True).stdout)
packages = {p["id"]: p for p in meta["packages"]}
nodes = {n["id"]: n for n in meta["resolve"]["nodes"]}
root = meta["resolve"]["root"]
seen, stack = set(), [root]
while stack:
    pid = stack.pop()
    if pid in seen:
        continue
    seen.add(pid)
    for dep in nodes[pid]["deps"]:
        if any(k["kind"] is None for k in dep["dep_kinds"]):  # normal dependencies (not build / dev)
            stack.append(dep["pkg"])
seen.discard(root)
rows = sorted((packages[i]["name"], packages[i]["version"], packages[i]["license"] or "?", packages[i].get("repository") or "")
              for i in seen)
lines = [
    "# Rust crates in the Mermaid import",
    "",
    "Linked statically into Animated Diagrams through merman (`third_party/merman`, `WITH_MERMAID`).",
    "Sources: https://crates.io (exact versions in `Cargo.lock`). The MPL-2.0 crates (cssparser, selectors,",
    "dtoa-short) are used unmodified; their source code is available at the repositories below.",
    "",
    "Generated by `list_crates.py`.",
    "",
    "| Crate | Version | License | Repository |",
    "|---|---|---|---|",
] + ["| %s | %s | %s | %s |" % r for r in rows]
(here / "CRATES.md").write_text("\n".join(lines) + "\n")
print(f"{len(rows)} crates")
